  [inst_1 : CommSemiring R] (self : Combinatorics.MultiplicativeWeight D R) {S : Finset α} (d : D.Object S),
  self.objectWeight d = ∏ B, self.connectedWeight (((D.decompose S) d).snd B)

∀ {n : ℕ} (pairing : Combinatorics.Pairing (n + 1)) (i : Fin (2 * n)),
  pairing.eraseZeroPair.partner i =
    have hzero := ⋯;
    have e := Combinatorics.FiniteIndex.deletedPositionsOrderIso n (pairing.partner 0) hzero;
    e.symm (pairing.restrictedPartner (e i))

∀ {a b n : ℕ} (e : Combinatorics.PositionSplitting a b n) {P : Combinatorics.Pairing n}
  (h : Combinatorics.Pairing.IsSplit e P),
  Combinatorics.Pairing.ofSplit e (Combinatorics.Pairing.splitLeft e h) (Combinatorics.Pairing.splitRight e h) = P

∀ {a b n : ℕ} (e : Combinatorics.PositionSplitting a b n) {P : Combinatorics.Pairing n}
  (h : Combinatorics.Pairing.IsSplit e P) (i : Fin (2 * a)),
  P.partner (e (Sum.inl i)) = e (Sum.inl ((Combinatorics.Pairing.splitLeft e h).partner i))

∀ {a b n : ℕ} (e : Combinatorics.PositionSplitting a b n) {P : Combinatorics.Pairing n}
  (h : Combinatorics.Pairing.IsSplit e P) (i : Fin (2 * b)),
  P.partner (e (Sum.inr i)) = e (Sum.inr ((Combinatorics.Pairing.splitRight e h).partner i))

