∀ {κ : ℝ} {potential : ℝ → ℝ} {hpotential : MeasureTheory.MemLp (fun x => ↑(potential x)) ⊤ MeasureTheory.volume}
  {evolution : QuantumMechanics.SingleParticle.Continuum.ContinuumSchrodingerEvolution1D κ potential hpotential}
  (self : QuantumMechanics.SingleParticle.Continuum.ContinuumSchwartzEvolutionRepresentative1D evolution) (t x : ℝ),
  HasDerivAt (fun τ => ((self.wavefunction τ) x).im) (self.timeDerivative t x).im t

∀ {κ : ℝ} {potential : ℝ → ℝ} {hpotential : MeasureTheory.MemLp (fun x => ↑(potential x)) ⊤ MeasureTheory.volume}
  {evolution : QuantumMechanics.SingleParticle.Continuum.ContinuumSchrodingerEvolution1D κ potential hpotential}
  (self : QuantumMechanics.SingleParticle.Continuum.ContinuumSchwartzEvolutionRepresentative1D evolution) (t x : ℝ),
  HasDerivAt (fun τ => ((self.wavefunction τ) x).re) (self.timeDerivative t x).re t

∀ {κ : ℝ} {potential : ℝ → ℝ} {hpotential : MeasureTheory.MemLp (fun x => ↑(potential x)) ⊤ MeasureTheory.volume}
  {evolution : QuantumMechanics.SingleParticle.Continuum.ContinuumSchrodingerEvolution1D κ potential hpotential}
  (self : QuantumMechanics.SingleParticle.Continuum.ContinuumSchwartzEvolutionRepresentative1D evolution) (t : ℝ),
  (self.wavefunction t).toLp 2 MeasureTheory.volume =
    (evolution.propagator t) ((self.wavefunction 0).toLp 2 MeasureTheory.volume)

∀ {κ : ℝ} {potential : ℝ → ℝ} {hpotential : MeasureTheory.MemLp (fun x => ↑(potential x)) ⊤ MeasureTheory.volume}
  {evolution : QuantumMechanics.SingleParticle.Continuum.ContinuumSchrodingerEvolution1D κ potential hpotential}
  (self : QuantumMechanics.SingleParticle.Continuum.ContinuumSchwartzEvolutionRepresentative1D evolution) (t x : ℝ),
  Complex.I * ↑evolution.hbar * self.timeDerivative t x =
    -↑κ * (QuantumMechanics.SingleParticle.Continuum.schwartzSpatialSecondDerivative1D (self.wavefunction t)) x +
      ↑(potential x) * (self.wavefunction t) x

∀ {κ : ℝ} {potential : ℝ → ℝ} {hpotential : MeasureTheory.MemLp (fun x => ↑(potential x)) ⊤ MeasureTheory.volume}
  {evolution : QuantumMechanics.SingleParticle.Continuum.ContinuumSchrodingerEvolution1D κ potential hpotential}
  (representative : QuantumMechanics.SingleParticle.Continuum.ContinuumSchwartzEvolutionRepresentative1D evolution)
  (t : ℝ),
  (QuantumMechanics.SingleParticle.Continuum.totalProbability1D fun x => (representative.wavefunction t) x) =
    QuantumMechanics.SingleParticle.Continuum.totalProbability1D fun x => (representative.wavefunction 0) x

