∀ {ExternalLabel : Type u_1} {InternalLabel : Type u_2} {N : ℕ} {S : Finset (Fin N)}
  (d : SecondQuantization.Common.TwoPointDiagram ExternalLabel InternalLabel N S),
  SecondQuantization.Common.TwoPointDiagram.ofSlotSplit ⋯ d.externalVacuumSplit.1 d.externalVacuumSplit.2 = d

∀ {ExternalLabel : Type u_1} {InternalLabel : Type u_2} {n : ℕ}
  (d : SecondQuantization.Common.TwoPointDiagram ExternalLabel InternalLabel n Finset.univ) (π : Equiv.Perm (Fin n)),
  (d.relabelInteractionVertices π).externalLabel = d.externalLabel

∀ {ExternalLabel : Type u_1} {InternalLabel : Type u_2} {n : ℕ}
  (d : SecondQuantization.Common.TwoPointDiagram ExternalLabel InternalLabel n Finset.univ) (π : Equiv.Perm (Fin n)),
  (d.relabelInteractionVertices π).relabelInteractionVertices (Equiv.symm π) = d

