  (d : SecondQuantization.Common.TwoPointDiagram ExternalLabel InternalLabel n Finset.univ) (π : Equiv.Perm (Fin n))
  (v : Fin n), (d.relabelInteractionVertices π).vertexLabel ⟨v, ⋯⟩ = d.vertexLabel ⟨π v, ⋯⟩

∀ {ExternalLabel : Type u_1} {InternalLabel : Type u_2} {N : ℕ} {S : Finset (Fin N)}
  (d : SecondQuantization.Common.TwoPointDiagram ExternalLabel InternalLabel N S)
  (v : SecondQuantization.Common.TwoPointVertex S), v ∈ d.componentBlock v

∀ {ExternalLabel : Type u_1} {InternalLabel : Type u_2} {N M : ℕ} {T : Finset (Fin N)} {U : Finset (Fin M)}
  (e : ↥T ≃ ↥U) (d : SecondQuantization.Common.TwoPointDiagram ExternalLabel InternalLabel N T),
  (SecondQuantization.Common.TwoPointDiagram.slotCongr e d).externalLabel = d.externalLabel

∀ {ExternalLabel : Type u_1} {InternalLabel : Type u_2} {N M : ℕ} {T : Finset (Fin N)} {U : Finset (Fin M)}
  (e : ↥T ≃ ↥U) (d : SecondQuantization.Common.TwoPointDiagram ExternalLabel InternalLabel N T),
  (SecondQuantization.Common.TwoPointDiagram.slotCongr e d).HasNoVacuumComponent ↔ d.HasNoVacuumComponent

