∀ {ExternalLabel : Type u_1} {InternalLabel : Type u_2} {N : ℕ} {S T : Finset (Fin N)} (h : T ⊆ S)
  (ext : SecondQuantization.Common.TwoPointDiagram ExternalLabel InternalLabel N T)
  (vac : SecondQuantization.Common.QuarticDiagram InternalLabel N (S \ T)) (v : ↥(S \ T)),
  have d := SecondQuantization.Common.TwoPointDiagram.ofSlotSplit h ext vac;
  have B := ⟨d.componentBlock (SecondQuantization.Common.slotSplitVacuumVertex v), ⋯⟩;
  B ∈ d.vacuumComponentParts

∀ {Config : Type u_1}
  (A : SecondQuantization.Common.AlgebraicFock Config →ₗ[ℂ] SecondQuantization.Common.AlgebraicFock Config)
  (n : Config), SecondQuantization.Common.diagonalCoeff A n = SecondQuantization.Common.matrixCoeff A n n

∀ {Config : Type u_1}
  {f g : SecondQuantization.Common.AlgebraicFock Config →ₗ[ℂ] SecondQuantization.Common.AlgebraicFock Config},
  (∀ (c : Config), f (SecondQuantization.Common.basisState c) = g (SecondQuantization.Common.basisState c)) → f = g

∀ {Config : Type u_1}
  {A B : SecondQuantization.Common.AlgebraicFock Config →ₗ[ℂ] SecondQuantization.Common.AlgebraicFock Config},
  (∀ (m n : Config), SecondQuantization.Common.matrixCoeff A m n = SecondQuantization.Common.matrixCoeff B m n) → A = B

∀ {Config : Type u_1}
  {A : SecondQuantization.Common.AlgebraicFock Config →ₗ[ℂ] SecondQuantization.Common.AlgebraicFock Config} {n : Config}
  {c : ℂ},
  A (SecondQuantization.Common.basisState n) = c • SecondQuantization.Common.basisState n →
    SecondQuantization.Common.matrixCoeff A n n = c

∀ {Config : Type u_1}
  (V : SecondQuantization.Common.AlgebraicFock Config →ₗ[ℂ] SecondQuantization.Common.AlgebraicFock Config)
  (n : Config), SecondQuantization.Common.reachableSupport V 0 n = {n}

∀ {Config : Type u_1}
  (V : SecondQuantization.Common.AlgebraicFock Config →ₗ[ℂ] SecondQuantization.Common.AlgebraicFock Config)
  (n : Config), (V (SecondQuantization.Common.basisState n)).support ⊆ SecondQuantization.Common.reachableSupport V 1 n

∀ {Mode : Type u_1} [inst : LinearOrder Mode] (i : Mode),
  (SecondQuantization.Fermionic.create i) SecondQuantization.Fermionic.fockVacuum =
    SecondQuantization.Fermionic.basisState {i}

∀ {Mode : Type u_1} [inst : LinearOrder Mode] [inst_1 : Fintype Mode] {i : Mode}
  {n : SecondQuantization.Fermionic.Occupation Mode},
  i ∈ n → (SecondQuantization.Fermionic.finiteHilbertCreate i) (SecondQuantization.Common.finiteHilbertBasisState n) = 0

∀ {Mode : Type u_1} [inst : LinearOrder Mode] [inst_1 : Fintype Mode] {n : ℕ} {i j : Mode} {M : Type u_2}
  [inst_2 : AddCommMonoid M] (F : SecondQuantization.Fermionic.FixedExternalTwoPointWickDiagram Mode n i j → M),
  ∑ d, F d = ∑ T ∈ Finset.univ.powerset, ∑ p, F ↑((SecondQuantization.Fermionic.fixedExternalFiberEquiv T).symm p)

∀ {X : Type u_1} {Y : Type u_2} [inst : TopologicalSpace X] [inst_1 : TopologicalSpace Y] {n : ℕ}
  {f : X → (Fin (n + 1) → ℝ) → Y},
  Continuous (Function.uncurry f) → Continuous (Function.uncurry fun y rest => f y.1 (Fin.cons y.2 rest))

∀ {a b n : ℕ} (e : Combinatorics.PositionSplitting a b n) {P : Combinatorics.Pairing n}
  (h : Combinatorics.Pairing.IsSplit e P) (i : Fin (2 * a)),
  P.partner (e (Sum.inl i)) = e (Sum.inl (Combinatorics.splitLeftMap✝ e h i))

∀ {a b n : ℕ} (e : Combinatorics.PositionSplitting a b n) {P : Combinatorics.Pairing n}
  (h : Combinatorics.Pairing.IsSplit e P) (i : Fin (2 * b)),
  P.partner (e (Sum.inr i)) = e (Sum.inr (Combinatorics.splitRightMap✝ e h i))

∀ {ExternalLabel : Type u_1} {InternalLabel : Type u_2} {N : ℕ} {S : Finset (Fin N)}
  (d : SecondQuantization.Common.TwoPointDiagram ExternalLabel InternalLabel N S) (leg : Fin (2 * (2 * S.card + 1))),
  d.legInComponent (↑d.externalComponentPart) leg → ∃ i, d.externalSlotLegSplitting (Sum.inl i) = leg

∀ {InternalLabel : Type u_2} {N : ℕ} {S : Finset (Fin N)}
  (d : SecondQuantization.Common.QuarticDiagram InternalLabel N S) (C : ↥d.componentPartition.parts),
  d.componentBlock (SecondQuantization.Common.QuarticDiagram.componentRepresentative✝ d C) = ↑C

∀ {Mode : Type u_1} {i j : Mode} {m k : ℕ} (shuffle : Combinatorics.BinaryShuffle.SlotShuffle m k)
  (ext : { d // SecondQuantization.Common.TwoPointDiagram.IsExternallyConnected ↑d })
  (x : SecondQuantization.Common.OrderedQuarticDiagramData (SecondQuantization.Fermionic.QuarticVertexLabel Mode) k),
  have p := (SecondQuantization.Fermionic.fixedExternalShuffleFiberDataEquiv shuffle).symm (ext, x);
  have d := (SecondQuantization.Fermionic.fixedExternalFiberEquiv shuffle.leftSlots).symm p;
  (↑d).externalPiece ≍ ↑ext
